-- R47 (26 Oct 2026): the client's new "Kit Cost" price list replaces the whole product catalogue.
-- Every old product except the four class kits is removed (the same way "Delete product" works: quotation, order and
-- invoice lines keep their text and prices, only the link to the product goes). The class kits K01–K04 keep their
-- records and get the new names, prices, MRPs and contents; O01–O10 are the "Other Note book" items (no prices yet).
-- The old catalogue is kept for reference in src/lib/kits-old.ts and docs/OLD_PRICE_LIST.md.
UPDATE "QuotationItem" SET "productId" = NULL WHERE "productId" IN (SELECT "id" FROM "Product" WHERE "code" NOT IN ('K01', 'K02', 'K03', 'K04'));
UPDATE "SalesOrderItem" SET "productId" = NULL WHERE "productId" IN (SELECT "id" FROM "Product" WHERE "code" NOT IN ('K01', 'K02', 'K03', 'K04'));
UPDATE "InvoiceItem" SET "productId" = NULL WHERE "productId" IN (SELECT "id" FROM "Product" WHERE "code" NOT IN ('K01', 'K02', 'K03', 'K04'));
DELETE FROM "OpportunityItem" WHERE "productId" IN (SELECT "id" FROM "Product" WHERE "code" NOT IN ('K01', 'K02', 'K03', 'K04'));
DELETE FROM "LeadInterest" WHERE "productId" IN (SELECT "id" FROM "Product" WHERE "code" NOT IN ('K01', 'K02', 'K03', 'K04'));
DELETE FROM "Product" WHERE "id" IN (SELECT "id" FROM "Product" WHERE "code" NOT IN ('K01', 'K02', 'K03', 'K04'));

